import json
import re


def obj(value):
    return value if isinstance(value, dict) else {}


def text(value, limit=500):
    return value.strip()[:limit] if isinstance(value, str) else ""


def items(value):
    return value if isinstance(value, list) else []


def parse(value):
    if isinstance(value, dict):
        return value
    try:
        return obj(json.loads(value))
    except (ValueError, TypeError):
        return {}


def model_json(value):
    value = text(value, 50000)
    start, end = value.find("{"), value.rfind("}")
    return parse(value[start:end + 1]) if start >= 0 and end > start else {}


def encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def selected_seat(payload):
    passengers, interaction = obj(payload.get("passengers")), obj(payload.get("interaction"))
    raw = passengers.get("selected_seat") or interaction.get("current_speaker") or passengers.get("selected_seat_label")
    aliases = {"主驾": "driver", "副驾": "front", "后排左": "rearLeft", "后排右": "rearRight", "rear_left": "rearLeft", "rear_right": "rearRight"}
    raw = text(raw)
    raw = aliases.get(raw, raw)
    return raw if raw in ("driver", "front", "rearLeft", "rearRight") else "front"


def fact_catalog(payload):
    game = obj(payload.get("game"))
    plan = obj(payload.get("round_question_plan") or game.get("round_question_plan"))
    return [{"fact_key": text(s.get("fact_key"), 80), "question": obj(s.get("variants") or s.get("question_variants")).get("default", ""), "answer": text(s.get("expected_answer"), 20)}
            for s in items(plan.get("steps"))[:8] if isinstance(s, dict) and text(s.get("fact_key"), 80)]


def perception_snapshot(payload):
    event = obj(payload.get("event"))
    event_type = text(event.get("type"), 80)
    car = obj(payload.get("car"))
    signals = []
    if payload.get("trigger_type") == "chat" and text(payload.get("player_input")):
        labels = {"driver": "主驾", "front": "副驾", "rearLeft": "后排左", "rearRight": "后排右"}
        signals.append({"field": "player_input", "value": text(payload.get("player_input"), 160),
                        "label": labels[selected_seat(payload)] + "说", "source": "request"})
    if event_type == "environment_change":
        signals.append({"field": "environment", "value": event.get("value"),
                        "previous_value": event.get("previous_value"), "label": "车外环境", "source": "event"})
    elif event_type == "speed_overspeed":
        signals.append({"field": "speed", "value": event.get("value"), "unit": "km/h",
                        "previous_value": event.get("previous_value"), "threshold": event.get("threshold_kmh"),
                        "label": "车速", "source": "event"})
    elif event_type in {"driver_tired", "driver_distracted"}:
        labels = {"asleep": "睡着", "fatigued": "疲惫"}
        value = "分心" if event_type == "driver_distracted" else labels.get(event.get("state"), "疲惫")
        signals.append({"field": "driver_state", "value": value,
                        "duration_ms": event.get("duration_ms"), "label": "主驾状态", "source": "event"})
    elif event_type == "passenger_inactive":
        signals.append({"field": "participation", "value": "副驾持续未参与",
                        "duration_ms": event.get("duration_ms"), "label": "乘客参与", "source": "event"})
    elif event_type:
        labels = {"hard_brake": "急刹", "safety_pause": "安全暂停", "passenger_sleep": "乘客睡着",
                  "near_destination": "即将到达", "timeout": "本题超时", "round_timeout": "本题超时",
                  "game_end": "整局结束", "start_game": "开始游戏", "resume_game": "恢复游戏",
                  "near_answer": "接近答案", "game_stuck": "猜谜停滞", "cabin_laughing": "车内欢笑",
                  "passenger_question": "乘客提问"}
        signals.append({"field": "event", "value": labels.get(event_type, "收到座舱事件"), "label": "事件", "source": "event"})
    if not signals:
        for key, label in (("environment", "车外环境"), ("speed", "车速")):
            if key in car:
                signals.append({"field": key, "value": car[key], "label": label, "source": "request"})
    # Simulation inputs are observations, not a calibrated sensor confidence.
    return {"schema_version": 2, "source": "event" if event_type else "request",
            "signals": signals, "confidence": None}


def decision_trace(layer, rule, priority, decision, guard_status="passed", hint_blocked=False):
    return {
        "schema_version": 2,
        "layer": layer, "matched_rule": rule, "priority": priority,
        "strategy_id": rule, "decision": decision,
        "policy": "frontend_arbitrates_execution",
        "guard_status": guard_status, "hint_blocked": hint_blocked,
    }


def envelope(payload, line, priority="P2", status=None, correct=False, mode="normal", animation="speak", emotion="normal", reveal=False, seat=None, layer="llm", rule="realtime_director", guard_status="passed", hint_blocked=False, actions=None, decision="生成当前事件回复"):
    game = obj(payload.get("game"))
    status = status or game.get("status") or "playing"
    if status not in ("idle", "playing", "paused", "victory", "failed", "finished"):
        status = "playing"
    return {
        "intent": "answer_question", "reply_mode": "answer_only",
        "ai_reply_text": line, "covered_fact_keys": [], "passenger_action": None,
        "game_status": status, "is_correct": correct, "answer": text(game.get("current_answer"), 100),
        "ui_change": {"cabin_mode": mode, "target_seat": seat or selected_seat(payload), "host_emotion": emotion, "animation": animation, "show_answer": reveal},
        "priority": priority,
        "perception": perception_snapshot(payload),
        "decision_trace": decision_trace(layer, rule, priority, decision, guard_status, hint_blocked),
        "execution": {
            "kind": "plan",
            "actions": items(actions),
            "timing": {"owner": "frontend"},
            "fallback": "ignore_unapproved_or_failed_action",
        },
        "knowhow_status": "not_relevant",
        "retrieved_knowhow": [],
        "strategy": "direct_answer",
        "target_seat": None,
        "reason_codes": [],
        "applied_knowhow_ids": [],
        "speech": {"priority": priority, "max_duration_ms": 6000, "interruptible": priority != "P0"}
    }

import time


P0_EVENTS = {"temporary_interruption", "hard_brake", "safety_pause", "timeout", "round_timeout", "game_end", "answer_correct"}
SCENE_EVENTS = {"environment_change", "speed_overspeed", "driver_tired", "passenger_sleep",
                "driver_distracted", "driver_distracted", "driver_distracted", "driver_distracted", "passenger_wake", "near_destination", "game_stuck", "near_answer",
                "cabin_laughing", "resume_game", "round_changed", "passenger_inactive"}
PROACTIVE_EVENTS = {"environment_change", "speed_overspeed", "driver_tired", "passenger_inactive"}
SHARE_FIELDS = {"environment", "speed", "driver", "passengers", "progress", "destination", "participation"}
AWAKE_STATES = {"awake", "normal", "active", "happy", "excited", "calm", "清醒", "正常", "普通", "开心", "兴奋", "平静", "大笑", "沉默"}
SEATS = ("front", "rearLeft", "rearRight")


def model_json(value):
    raw = text(value, 50000)
    raw = re.sub(r"<think\b[^>]*>.*?</think\s*>", "", raw, flags=re.I | re.S).strip()
    if re.search(r"<think\b", raw, re.I):
        return {}
    raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I).strip()
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\{", raw):
        try:
            value, end = decoder.raw_decode(raw[match.start():])
            if isinstance(value, dict) and not raw[match.start() + end:].strip():
                return value
        except ValueError:
            continue
    return {}


def canonical_states(snapshot):
    passengers = obj(snapshot.get("passengers"))
    raw = obj(passengers.get("states")) or passengers
    result = {}
    for key, alias in (("driver", "driver"), ("front", "front"), ("rearLeft", "rear_left"), ("rearRight", "rear_right")):
        value = raw.get(key, raw.get(alias))
        if key == "driver" and value is None:
            value = snapshot.get("driver")
        if isinstance(value, dict):
            value = value.get("state") or value.get("mood")
        result[key] = text(value, 30) or "unknown"
    return result


def eligible_seats(snapshot, speaker=None):
    states = canonical_states(snapshot)
    return [seat for seat in SEATS if seat != speaker and states[seat] in AWAKE_STATES]


def scope(snapshot):
    game = obj(snapshot.get("game"))
    return {"game_id": text(snapshot.get("game_id") or game.get("game_id"), 100),
            "round_id": text(snapshot.get("round_id") or game.get("round_id"), 100),
            "scene_version": text(str(snapshot.get("scene_version", "")), 100)}


def participation_snapshot(snapshot):
    raw = obj(snapshot.get("participation"))
    if not raw:
        return {}
    result = {"seat": "front" if raw.get("seat") == "front" else "unknown",
              "invitation_declined": raw.get("invitation_declined") is True}
    for key in ("version", "inactive_duration_ms", "dialogue_silence_ms", "remaining_ms", "real_user_turn_count"):
        value = raw.get(key)
        if isinstance(value, (int, float)) and not isinstance(value, bool) and 0 <= value <= 3600000:
            result[key] = int(value)
    return result


def valid_participation_candidate(snapshot):
    event = obj(snapshot.get("event"))
    state = participation_snapshot(snapshot)
    return (event.get("source") == "participation_monitor" and event.get("seat") == "front"
            and state.get("seat") == "front" and "version" in state
            and state.get("inactive_duration_ms", 0) >= 20000
            and state.get("dialogue_silence_ms", 0) >= 2500
            and state.get("remaining_ms", 0) > 15000 and not state["invitation_declined"]
            and canonical_states(snapshot)["front"] in AWAKE_STATES
            and obj(snapshot.get("game")).get("status") == "playing")


def shareable_snapshot(snapshot):
    car, game = obj(snapshot.get("car")), obj(snapshot.get("game"))
    return {
        "environment": text(car.get("environment"), 100),
        "speed": car.get("speed") if isinstance(car.get("speed"), (int, float)) else None,
        "destination": text(car.get("destination"), 100),
        "driver": canonical_states(snapshot)["driver"],
        "passengers": canonical_states(snapshot),
        "participation": participation_snapshot(snapshot),
        "progress": {key: game.get(key) for key in ("status", "round_index", "total_rounds", "question_count", "max_questions")},
    }


def clean_snapshot(raw):
    source = parse(raw)
    game = obj(source.get("game"))
    # No frontend transcript or player text is allowed to become a second memory.
    result = {key: source[key] for key in ("game_id", "round_id", "scene_version", "car", "driver", "passengers", "event") if key in source}
    result["game"] = {key: game[key] for key in (
        "status", "current_answer", "current_theme", "round_index", "total_rounds", "question_count",
        "max_questions", "covered_fact_keys", "asked_questions", "round_question_plan", "game_id", "round_id",
    ) if key in game}
    result["game"]["asked_questions"] = items(game.get("asked_questions"))[-8:]
    result["game"]["covered_fact_keys"] = items(game.get("covered_fact_keys"))[-24:]
    result["passengers"] = {"states": canonical_states(source), "selected_seat": selected_seat(source)}
    result["participation"] = participation_snapshot(source)
    return result


def empty_knowhow(snapshot, status="not_relevant", speaker=None):
    return {"status": status, "retrieved": [], "eligible_target_seats": eligible_seats(snapshot, speaker)}


def valid_situation(raw, snapshot):
    cached = parse(raw)
    expected = scope(snapshot)
    now = int(time.time() * 1000)
    if not all(expected.values()) or any(cached.get(key) != value for key, value in expected.items()):
        return {}, "scope_mismatch"
    if cached.get("analysis_status") != "ready" or cached.get("usable_for_dialogue") is not True:
        return {}, "not_ready"
    try:
        generated, expires = int(cached["generated_at_ms"]), int(cached["expires_at_ms"])
        if not (generated <= now + 2000 and now < expires <= generated + 60000):
            return {}, "expired"
    except (KeyError, TypeError, ValueError):
        return {}, "invalid_expiry"
    return obj(cached.get("dialogue_context")), "valid"


def scene_envelope(snapshot, context=None, response=None, status="ready", speak=False, usable=False):
    now = int(time.time() * 1000)
    return {"schema_version": 1, "route": "situation", **scope(snapshot),
            "event_id": text(obj(snapshot.get("event")).get("id"), 100),
            "generated_at_ms": now, "expires_at_ms": now + 60000,
            "analysis_status": status, "usable_for_dialogue": usable,
            "dialogue_context": context or {}, "request_proactive_speech": speak,
            "host_response": response}


def valid_environment_change(snapshot):
    event, car = obj(snapshot.get("event")), obj(snapshot.get("car"))
    current, previous = text(car.get("environment"), 100), text(event.get("previous_value"), 100)
    return (event.get("type") == "environment_change" and bool(current) and bool(previous)
            and event.get("value") == current and previous != current
            and obj(snapshot.get("game")).get("status") in {"opening", "playing"})


def environment_rule_response(snapshot, fallback=False):
    environment = text(obj(snapshot.get("car")).get("environment"), 100)
    labels = {"高速路晴天白天": "驶上高速", "高速路晴天深夜": "驶上夜间的高速",
              "高速路雨天白天": "驶上雨中的高速", "城区晴天白天": "来到市区",
              "城区夜晚": "来到夜晚的市区", "城区雨天白天": "来到雨中的市区",
              "车库": "进入车库", "隧道": "进入隧道", "风景区晴天白天": "来到风景区",
              "风景区傍晚": "来到傍晚的风景区", "风景区雪景白天": "来到雪中的风景区",
              "风景区晴天深夜": "来到夜间的风景区"}
    line = "我们{}啦。".format(labels[environment]) if environment in labels else "车外环境变化啦，我们继续。"
    answer = text(obj(snapshot.get("game")).get("current_answer"), 100)
    if answer and answer in line:
        line = "我们继续。"
    result = envelope(snapshot, line, "P1", layer="fallback" if fallback else "rule",
                      rule="environment_announcement", decision="环境变化优先播报；话术由前端排队执行")
    result.update(intent="event", reply_mode="chat_only", strategy="soft_response", target_seat=None,
                  covered_fact_keys=[], applied_knowhow_ids=[], retrieved_knowhow=[], knowhow_status="not_relevant",
                  reason_codes=["environment_change"])
    result["execution"]["actions"] = []
    return result

def main(input_payload: str, cabin_snapshot: str) -> dict:
    payload = parse(input_payload)
    game, event = obj(payload.get("game")), obj(payload.get("event"))
    trigger = text(payload.get("trigger_type"), 30) or "event"
    event_type = text(event.get("type"), 80)
    priority = text(event.get("priority"), 2)
    if priority not in ("P0", "P1", "P2", "P3", "P4"):
        priority = "P2"
    answer = text(game.get("current_answer"), 100)
    utterance = text(payload.get("player_input"), 800)
    music_request = trigger == "chat" and bool(re.search(
        r"(?:打开|开启|播放|放|启动|关掉|关闭|停止|暂停|静音).{0,8}(?:背景音乐|音乐)|(?:背景音乐|音乐).{0,8}(?:打开|开启|播放|关掉|关闭|停止|暂停|静音)",
        utterance,
    ))
    normalize = lambda s: re.sub(r"[\s，。！？,.!?]", "", s.lower())
    guess, expected = normalize(utterance), normalize(answer)
    exact = bool(expected and trigger == "chat" and game.get("status") == "playing" and guess in
                 (expected, "答案是" + expected, "我猜" + expected, "我猜是" + expected, "是" + expected))
    p0_event = event_type in ("hard_brake", "safety_pause", "timeout", "round_timeout", "game_end")
    ended_game = trigger != "chat" and game.get("status") in ("victory", "failed", "finished") and not music_request
    p0 = p0_event or exact or ended_game
    interaction = obj(payload.get("interaction"))
    recent = [{k: text(message.get(k), 180) for k in ("role", "speaker", "seat", "text", "content") if text(message.get(k), 180)}
              for message in items(interaction.get("recent_messages"))[-8:] if isinstance(message, dict)]
    snapshot = parse(cabin_snapshot)
    context = {
        "trigger_type": trigger, "event": event, "player_input": utterance,
        "game": {k: game.get(k) for k in ("status", "current_answer", "current_theme", "round_index", "question_count", "max_questions", "covered_fact_keys")},
        "asked_questions": items(game.get("asked_questions"))[-8:], "recent_messages": recent,
        "fact_catalog": fact_catalog(payload), "car": obj(payload.get("car")),
        "perception": obj(payload.get("perception")), "cabin_snapshot": snapshot,
        "speaker_seat": selected_seat(payload),
        "speaker_persona": obj(interaction.get("current_speaker_persona") or obj(payload.get("passengers")).get("selected_persona"))
    }
    return {
        # Keep nested player payload serialized between Dify Code nodes. Dify
        # limits structured values to five levels; game plans can exceed that.
        "payload": encode(payload), "context_json": encode(context), "exact_correct": exact,
        "is_p0": p0, "event_type": event_type, "priority": priority,
        "perception": perception_snapshot(payload),
    }

FEEDBACK_IDS = {"HK10", "HK11", "HK12", "HK13", "HK14", "HK17"}
ALL_SEATS = {"driver", "front", "rearLeft", "rearRight"}


def count(value, maximum=100):
    return int(value) if isinstance(value, (int, float)) and not isinstance(value, bool) and 0 <= value <= maximum else 0


def host_preferences(snapshot):
    raw = obj(snapshot.get("host_preferences"))
    return {key: raw[key] if isinstance(raw.get(key), bool) else default
            for key, default in (("praise", True), ("brief", False), ("invitations", True), ("independent", False))}


def performance_snapshot(snapshot):
    raw = obj(snapshot.get("performance"))
    result = {key: count(raw.get(key)) for key in ("completed_rounds", "team_correct", "streak_count", "consecutive_unsolved")}
    result["per_seat_correct"] = {seat: count(obj(raw.get("per_seat_correct")).get(seat)) for seat in ALL_SEATS}
    result["streak_seat"] = raw.get("streak_seat") if raw.get("streak_seat") in ALL_SEATS else None
    result["recent_results"] = [{"round_index": count(row.get("round_index")),
                                 "correct_seat": row.get("correct_seat") if row.get("correct_seat") in ALL_SEATS else None}
                                for row in items(raw.get("recent_results"))[-3:] if isinstance(row, dict)]
    last = obj(raw.get("last_result"))
    result["last_result"] = {"round_index": count(last.get("round_index")),
                             "correct_seat": last.get("correct_seat") if last.get("correct_seat") in ALL_SEATS else None,
                             "contributors": list(dict.fromkeys(seat for seat in items(last.get("contributors")) if seat in ALL_SEATS))}
    return result


def feedback_snapshot(snapshot):
    raw = obj(snapshot.get("host_feedback"))
    return {"id": text(raw.get("id"), 140), "subject_seat": raw.get("subject_seat") if raw.get("subject_seat") in ALL_SEATS else None,
            "selected_id": text(raw.get("selected_id"), 10),
            "candidate_ids": [key for key in items(raw.get("candidate_ids"))[:3] if key in FEEDBACK_IDS],
            "contributors": list(dict.fromkeys(seat for seat in items(raw.get("contributors")) if seat in ALL_SEATS)),
            **{key: count(raw.get(key)) for key in ("team_correct", "personal_correct", "streak_count", "previous_unsolved")}}


def valid_result_feedback(snapshot):
    event, game = obj(snapshot.get("event")), obj(snapshot.get("game"))
    feedback, performance = feedback_snapshot(snapshot), performance_snapshot(snapshot)
    subject = feedback["subject_seat"]
    if (event.get("type") != "post_result_feedback" or event.get("source") != "performance_monitor"
            or game.get("status") != "victory" or not host_preferences(snapshot)["praise"]
            or not feedback["id"] or subject not in ALL_SEATS
            or performance["last_result"]["correct_seat"] != subject
            or performance["last_result"]["round_index"] != game.get("round_index")
            or feedback["team_correct"] != performance["team_correct"]
            or feedback["personal_correct"] != performance["per_seat_correct"][subject]
            or feedback["streak_count"] != performance["streak_count"]):
        return False
    recent = performance["recent_results"]
    valid = set()
    if feedback["team_correct"] == 6:
        valid.add("HK10")
    if performance["streak_seat"] == subject and feedback["streak_count"] in (2, 3):
        valid.add("HK11")
    if feedback["personal_correct"] == 6:
        valid.add("HK12")
    if feedback["personal_correct"] == 1:
        valid.add("HK13")
    if feedback["previous_unsolved"] >= 2 and len(recent) == 3 and all(row["correct_seat"] is None for row in recent[:-1]):
        valid.add("HK14")
    if len(feedback["contributors"]) >= 2 and set(feedback["contributors"]) == set(performance["last_result"]["contributors"]):
        valid.add("HK17")
    return bool(feedback["candidate_ids"] and feedback["selected_id"] in feedback["candidate_ids"]
                and set(feedback["candidate_ids"]).issubset(valid))


_experience_clean_snapshot = clean_snapshot


def clean_snapshot(raw):
    source = parse(raw)
    current = _experience_clean_snapshot(raw)
    current.update(host_preferences=host_preferences(source), performance=performance_snapshot(source),
                   host_feedback=feedback_snapshot(source))
    return current


_experience_shareable_snapshot = shareable_snapshot


def shareable_snapshot(snapshot):
    return {**_experience_shareable_snapshot(snapshot), "performance": performance_snapshot(snapshot),
            "host_preferences": host_preferences(snapshot), "feedback": feedback_snapshot(snapshot)}

_normalize_original = main


def valid_environment_change(snapshot):
    event, car = obj(snapshot.get("event")), obj(snapshot.get("car"))
    current, previous = text(car.get("environment"), 100), text(event.get("previous_value"), 100)
    return (event.get("type") == "environment_change" and bool(current) and bool(previous)
            and event.get("value") == current and previous != current
            and obj(snapshot.get("game")).get("status") in {"opening", "playing"})


def main(snapshot: str) -> dict:
    current = clean_snapshot(snapshot)
    current["trigger_type"] = "event"
    current["player_input"] = ""
    event = obj(current.get("event"))
    kind = text(event.get("type"), 80)
    event["priority"] = "P0" if kind in P0_EVENTS else "P1" if kind in {"environment_change", "speed_overspeed", "driver_tired", "driver_distracted"} else "P2" if kind in {"passenger_sleep", "near_destination"} else "P4" if kind in {"passenger_inactive", "cabin_laughing"} else "P3"
    current["event"] = event
    normalized = _normalize_original(encode(current), "{}")
    normalized["is_p0"] = normalized["is_p0"] or kind in P0_EVENTS
    valid = kind in SCENE_EVENTS and all(scope(current).values()) and bool(text(event.get("id")))
    if kind == "driver_tired":
        duration = event.get("duration_ms")
        state = text(event.get("state"), 30)
        valid = valid and isinstance(duration, (int, float)) and duration > 15000 and state in {"fatigued", "asleep", "疲惫", "睡着"}
    if kind == "speed_overspeed":
        before, after = event.get("previous_value"), event.get("value")
        valid = valid and isinstance(before, (int, float)) and isinstance(after, (int, float)) and before <= 120 < after
    if kind == "passenger_inactive":
        valid = valid and valid_participation_candidate(current)
    if kind == "environment_change":
        valid = valid and valid_environment_change(current)
    if obj(current.get("game")).get("status") == "paused":
        valid = False
    scene = {"event_type": kind, "snapshot": shareable_snapshot(current),
             "eligible_collaborators": ["front"] if kind == "passenger_inactive" and valid else eligible_seats(current),
             "proactive_allowed": valid and kind in SCENE_EVENTS and kind not in {"round_changed", "resume_game"},
             "active_constraints": ["睡眠和未知状态乘员不可邀请，主驾不可邀请", "暂停时不得推进游戏", "不得提供谜底或额外提示", "动作执行和抢占只由前端负责"]}
    # Do not expose arbitrary event.value or hidden game facts to the analyst/RAG.
    normalized["context_json"] = encode(scene)
    normalized["can_analyze"] = bool(valid and not normalized["is_p0"])
    normalized["priority_fast_path"] = bool(valid and event["priority"] == "P1" and not normalized["is_p0"])
    return normalized

_experience_scene_input = main


def main(snapshot: str) -> dict:
    result = _experience_scene_input(snapshot)
    current = clean_snapshot(snapshot)
    feedback_event = obj(current.get("event")).get("type") == "post_result_feedback"
    result["feedback_fast_path"] = False
    if feedback_event:
        valid = valid_result_feedback(current) and all(scope(current).values()) and bool(text(obj(current.get("event")).get("id")))
        current["event"]["priority"] = "P4"
        result.update(payload=encode(current), is_p0=False, can_analyze=bool(valid),
                      feedback_fast_path=bool(valid), priority="P4")
        context = {"event_type": "post_result_feedback", "snapshot": shareable_snapshot(current),
                   "eligible_collaborators": [], "proactive_allowed": bool(valid),
                   "active_constraints": ["只认可可信统计中的表现", "P0完成后才由前端决定播出", "不改变游戏或车辆状态"]}
        result["context_json"] = encode(context)
    return result

