                  reason_codes=["environment_change"])
    result["execution"]["actions"] = []
    return result

def main(analysis_text: str, context_json: str) -> dict:
    scene = parse(context_json)
    value = model_json(analysis_text)
    valid = isinstance(value.get("needs_knowhow"), bool) and isinstance(value.get("share_context"), bool)
    fields = [key for key in items(value.get("selected_fields")) if isinstance(key, str) and key in SHARE_FIELDS]
    fields = list(dict.fromkeys(fields))
    share = valid and value.get("share_context") is True and bool(fields)
    need = valid and value.get("needs_knowhow") is True
    allowed = scene.get("proactive_allowed") is True
    scene["analysis_plan"] = {
        "share_context": share, "selected_fields": fields if share else [],
        "proactive_speech": valid and allowed and value.get("proactive_speech") is True,
        "analysis_valid": valid,
    }
    # Retrieval uses only trusted current observations, never the model's free text.
    scene["knowhow"] = {"status": "not_relevant" if valid else "failed", "retrieved": [],
                        "eligible_target_seats": items(scene.get("eligible_collaborators"))}
    kind = scene.get("event_type", "")
    event_topics = {
        "environment_change": ("环境变化何时回应、何时不打断", ["environment"]),
        "passenger_sleep": ("乘员睡着时轻柔关怀，不邀请睡眠乘员", ["passengers"]),
        "passenger_wake": ("乘员醒来后互动恢复", ["passengers"]),
        "passenger_inactive": ("真实副驾持续未参与时是否自然邀请，尊重独立思考且不打断问答", ["participation", "passengers", "progress"]),
        "driver_tired": ("主驾疲惫或睡着的关怀，不分散驾驶注意力", ["driver"]),
        "speed_overspeed": ("车速超限，简短关怀驾驶安全", ["speed"]),
        "near_destination": ("临近目的地如何自然收尾", ["destination", "progress"]),
        "game_stuck": ("玩家卡壳与连续猜错，鼓励而不提供额外提示", ["progress", "passengers"]),
        "resume_game": ("游戏被打断后的恢复", ["progress"]),
    }
    topic, relevant = event_topics.get(kind, (kind, ["progress"]))
    facts = {key: obj(scene.get("snapshot")).get(key) for key in relevant}
    query = "主持经验：{}；当前状态：{}；不得泄露答案或推进暂停中的游戏。".format(topic, encode(facts))
    return {"needs_knowhow": bool(need), "knowhow_query": query if need else "",
            "director_context": encode(scene),
            "eligible_target_seats": encode(items(scene.get("eligible_collaborators")))}

import json
import re


KNOWN_KNOWHOW = {"HK{:02d}".format(index) for index in range(1, 29)}


def obj(value):
    return value if isinstance(value, dict) else {}


def items(value):
    return value if isinstance(value, list) else []


def text(value, limit=4000):
    return value.strip()[:limit] if isinstance(value, str) else ""


def parse(value):
    if isinstance(value, dict):
        return value
    try:
        parsed = json.loads(value)
        return parsed if isinstance(parsed, dict) else {}
    except (ValueError, TypeError):
        return {}


def content_record(chunk):
    raw = text(chunk.get("content") or chunk.get("segment_content"), 4000)
    record = {}
    try:
        decoded = json.loads(raw)
        if isinstance(decoded, dict):
            record = decoded
    except (ValueError, TypeError):
        pass
    knowhow_id = text(record.get("knowhow_id"), 20)
    if not knowhow_id:
        match = re.search(r'"knowhow_id"\s*:\s*"(HK\d{2})"', raw)
        knowhow_id = match.group(1) if match else ""
    title = text(record.get("title") or chunk.get("title") or obj(chunk.get("metadata")).get("title"), 120)
    return knowhow_id, title, raw


def make_context(context_json, chunks, status):
    context = parse(context_json)
    retrieved = []
    malformed = False
    for chunk in items(chunks)[:3]:
        if not isinstance(chunk, dict):
            malformed = True
            continue
        knowhow_id, title, content = content_record(chunk)
        if knowhow_id not in KNOWN_KNOWHOW or not content:
            malformed = True
            continue
        if all(row["knowhow_id"] != knowhow_id for row in retrieved):
            retrieved.append({"knowhow_id": knowhow_id, "title": title or knowhow_id, "content": content})

    if malformed:
        status = "failed"
        retrieved = []
    elif retrieved:
        status = "used"
    else:
        status = "empty"

    context["knowhow"] = {
        "status": status,
        "retrieved": retrieved,
        "eligible_target_seats": [],
        "retrieval_policy": "up_to_3_no_rerank",
    }
    return json.dumps(context, ensure_ascii=False, separators=(",", ":")), status, [
        {"knowhow_id": row["knowhow_id"], "title": row["title"]} for row in retrieved
    ]


def main(context_json: str, retrieval_results: list, eligible_target_seats: str) -> dict:
    director_context, status, retrieved = make_context(context_json, retrieval_results, "used")
    parsed = parse(director_context)
    knowhow = obj(parsed.get("knowhow"))
    eligible = items(json.loads(eligible_target_seats))
    knowhow["eligible_target_seats"] = eligible
    parsed["knowhow"] = knowhow
    return {
        "director_context": json.dumps(parsed, ensure_ascii=False, separators=(",", ":")),
        "knowhow_status": status,
        "retrieved_knowhow": json.dumps(retrieved, ensure_ascii=False, separators=(",", ":")),
    }


def main_without_retrieval(context_json: str, eligible_target_seats: str) -> dict:
    context = parse(context_json)
    eligible = items(json.loads(eligible_target_seats))
    context["knowhow"] = {
        "status": "not_relevant",
        "retrieved": [],
        "eligible_target_seats": eligible,
        "retrieval_policy": "skipped_by_rule",
    }
    return {"director_context": json.dumps(context, ensure_ascii=False, separators=(",", ":"))}

_retrieval_context_original = main


def main(context_json: str, retrieval_results: list, eligible_target_seats: str) -> dict:
    result = _retrieval_context_original(context_json, retrieval_results, eligible_target_seats)
    context = parse(result["director_context"])
    knowhow = obj(context.get("knowhow"))
    kind = context.get("event_type")
    applicable = {"game_stuck": {"HK01"}, "environment_change": {"HK06"},
                  "resume_game": {"HK08"}, "near_destination": {"HK09"},
                  "cabin_laughing": {"HK07"},
                  "passenger_inactive": {"HK28"}}.get(kind, set())
    states = obj(obj(context.get("snapshot")).get("passengers"))
    if kind == "post_result_feedback":
        applicable = set(items(obj(obj(context.get("snapshot")).get("feedback")).get("candidate_ids")))
    if any(state in {"sleeping", "asleep", "睡着"} for state in states.values()):
        applicable = applicable | {"HK05"}
    knowhow["retrieval_hits"] = json.loads(result["retrieved_knowhow"])
    knowhow["retrieved"] = [row for row in items(knowhow.get("retrieved")) if row.get("knowhow_id") in applicable]
    if knowhow.get("status") == "used" and not knowhow["retrieved"]:
        knowhow["status"] = "not_relevant"
    context["knowhow"] = knowhow
    result["director_context"] = json.dumps(context, ensure_ascii=False, separators=(",", ":"))
    result["knowhow_status"] = knowhow["status"]
    return result

import json
import re


def obj(value):
    return value if isinstance(value, dict) else {}


def text(value, limit=500):
    return value.strip()[:limit] if isinstance(value, str) else ""


def items(value):
    return value if isinstance(value, list) else []


def parse(value):
    if isinstance(value, dict):
        return value
    try:
        return obj(json.loads(value))
    except (ValueError, TypeError):
        return {}


def model_json(value):
    value = text(value, 50000)
    start, end = value.find("{"), value.rfind("}")
    return parse(value[start:end + 1]) if start >= 0 and end > start else {}


def encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def selected_seat(payload):
    passengers, interaction = obj(payload.get("passengers")), obj(payload.get("interaction"))
    raw = passengers.get("selected_seat") or interaction.get("current_speaker") or passengers.get("selected_seat_label")
    aliases = {"主驾": "driver", "副驾": "front", "后排左": "rearLeft", "后排右": "rearRight", "rear_left": "rearLeft", "rear_right": "rearRight"}
    raw = text(raw)
    raw = aliases.get(raw, raw)
    return raw if raw in ("driver", "front", "rearLeft", "rearRight") else "front"


def fact_catalog(payload):
    game = obj(payload.get("game"))
    plan = obj(payload.get("round_question_plan") or game.get("round_question_plan"))
    return [{"fact_key": text(s.get("fact_key"), 80), "question": obj(s.get("variants") or s.get("question_variants")).get("default", ""), "answer": text(s.get("expected_answer"), 20)}
            for s in items(plan.get("steps"))[:8] if isinstance(s, dict) and text(s.get("fact_key"), 80)]


def perception_snapshot(payload):
    event = obj(payload.get("event"))
    event_type = text(event.get("type"), 80)
    car = obj(payload.get("car"))
    signals = []
    if payload.get("trigger_type") == "chat" and text(payload.get("player_input")):
        labels = {"driver": "主驾", "front": "副驾", "rearLeft": "后排左", "rearRight": "后排右"}
        signals.append({"field": "player_input", "value": text(payload.get("player_input"), 160),
                        "label": labels[selected_seat(payload)] + "说", "source": "request"})
    if event_type == "environment_change":
        signals.append({"field": "environment", "value": event.get("value"),
                        "previous_value": event.get("previous_value"), "label": "车外环境", "source": "event"})
    elif event_type == "speed_overspeed":
        signals.append({"field": "speed", "value": event.get("value"), "unit": "km/h",
                        "previous_value": event.get("previous_value"), "threshold": event.get("threshold_kmh"),
                        "label": "车速", "source": "event"})
    elif event_type in {"driver_tired", "driver_distracted"}:
        labels = {"asleep": "睡着", "fatigued": "疲惫"}
        value = "分心" if event_type == "driver_distracted" else labels.get(event.get("state"), "疲惫")
        signals.append({"field": "driver_state", "value": value,
                        "duration_ms": event.get("duration_ms"), "label": "主驾状态", "source": "event"})
    elif event_type == "passenger_inactive":
        signals.append({"field": "participation", "value": "副驾持续未参与",
                        "duration_ms": event.get("duration_ms"), "label": "乘客参与", "source": "event"})
    elif event_type:
        labels = {"hard_brake": "急刹", "safety_pause": "安全暂停", "passenger_sleep": "乘客睡着",
                  "near_destination": "即将到达", "timeout": "本题超时", "round_timeout": "本题超时",
                  "game_end": "整局结束", "start_game": "开始游戏", "resume_game": "恢复游戏",
                  "near_answer": "接近答案", "game_stuck": "猜谜停滞", "cabin_laughing": "车内欢笑",
                  "passenger_question": "乘客提问"}
        signals.append({"field": "event", "value": labels.get(event_type, "收到座舱事件"), "label": "事件", "source": "event"})
    if not signals:
        for key, label in (("environment", "车外环境"), ("speed", "车速")):
            if key in car:
                signals.append({"field": key, "value": car[key], "label": label, "source": "request"})
    # Simulation inputs are observations, not a calibrated sensor confidence.
    return {"schema_version": 2, "source": "event" if event_type else "request",
            "signals": signals, "confidence": None}


def decision_trace(layer, rule, priority, decision, guard_status="passed", hint_blocked=False):
    return {
        "schema_version": 2,
        "layer": layer, "matched_rule": rule, "priority": priority,
        "strategy_id": rule, "decision": decision,
        "policy": "frontend_arbitrates_execution",
        "guard_status": guard_status, "hint_blocked": hint_blocked,
    }


def envelope(payload, line, priority="P2", status=None, correct=False, mode="normal", animation="speak", emotion="normal", reveal=False, seat=None, layer="llm", rule="realtime_director", guard_status="passed", hint_blocked=False, actions=None, decision="生成当前事件回复"):
    game = obj(payload.get("game"))
    status = status or game.get("status") or "playing"
    if status not in ("idle", "playing", "paused", "victory", "failed", "finished"):
        status = "playing"
    return {
        "intent": "answer_question", "reply_mode": "answer_only",
        "ai_reply_text": line, "covered_fact_keys": [], "passenger_action": None,
        "game_status": status, "is_correct": correct, "answer": text(game.get("current_answer"), 100),
        "ui_change": {"cabin_mode": mode, "target_seat": seat or selected_seat(payload), "host_emotion": emotion, "animation": animation, "show_answer": reveal},
        "priority": priority,
        "perception": perception_snapshot(payload),
        "decision_trace": decision_trace(layer, rule, priority, decision, guard_status, hint_blocked),
        "execution": {
            "kind": "plan",
            "actions": items(actions),
            "timing": {"owner": "frontend"},
            "fallback": "ignore_unapproved_or_failed_action",
        },
        "knowhow_status": "not_relevant",
        "retrieved_knowhow": [],
        "strategy": "direct_answer",
        "target_seat": None,
        "reason_codes": [],
        "applied_knowhow_ids": [],
        "speech": {"priority": priority, "max_duration_ms": 6000, "interruptible": priority != "P0"}
    }

