    return (event.get("source") == "participation_monitor" and event.get("seat") == "front"
            and state.get("seat") == "front" and "version" in state
            and state.get("inactive_duration_ms", 0) >= 20000
            and state.get("dialogue_silence_ms", 0) >= 2500
